

import typing

import pydantic
from ..core.pydantic_utilities import IS_PYDANTIC_V2, UniversalBaseModel
from .compaction_summary_item_param_type import CompactionSummaryItemParamType


class CompactionSummaryItemParam(UniversalBaseModel):
    """
    A compaction item generated by the [`v1/responses/compact` API](/docs/api-reference/responses/compact).
    """

    id: typing.Optional[str] = pydantic.Field(default=None)
    """
    The ID of the compaction item.
    """

    type: CompactionSummaryItemParamType = pydantic.Field()
    """
    The type of the item. Always `compaction`.
    """

    encrypted_content: str = pydantic.Field()
    """
    The encrypted content of the compaction summary.
    """

    if IS_PYDANTIC_V2:
        model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(extra="allow", frozen=True)
    else:

        class Config:
            frozen = True
            smart_union = True
            extra = pydantic.Extra.allow
